use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl SyscallAstTransformer { pub fn new (interceptor : SyscallInterceptor) -> Self { Self { interceptor , transformations : HashMap :: new () , } } pub fn transform_file (& mut self , file_path : & Path) -> Result < String > { let content = std :: fs :: read_to_string (file_path) ? ; let mut syntax_tree : File = syn :: parse_str (& content) ? ; self . visit_file_mut (& mut syntax_tree) ; Ok (syntax_tree . to_token_stream () . to_string ()) } fn wrap_syscall (& mut self , call_expr : & Expr , wrapper : & SyscallWrapper) -> TokenStream { let original = call_expr . to_token_stream () ; let wrapper_macro = & wrapper . wrapper_macro ; let oracle_type = & wrapper . oracle_type ; let safety_wrapper = & wrapper . safety_wrapper ; * self . transformations . entry (wrapper . original_call . clone ()) . or_insert (0) += 1 ; match (& wrapper . mock_implementation , self . interceptor . mock_mode) { (Some (mock_impl) , true) => { let mock_tokens : TokenStream = mock_impl . parse () . unwrap_or_else (| _ | quote ! { mock_default () }) ; quote ! { # wrapper_macro ! { oracle_type : # oracle_type , safety_wrapper : # safety_wrapper , mock : # mock_tokens , original : # original } } } _ => { match self . interceptor . type_safety_level { TypeSafetyLevel :: Permissive => { quote ! { # wrapper_macro ! { log_syscall (# original) } } } TypeSafetyLevel :: Strict => { quote ! { # wrapper_macro ! { type_safe_syscall ::<# oracle_type > (# original) } } } TypeSafetyLevel :: Paranoid => { let default_policy = "default_policy" . to_string () ; let dao_policy = wrapper . dao_policy . as_ref () . unwrap_or (& default_policy) ; quote ! { # wrapper_macro ! { dao_governed_syscall ::<# oracle_type > (# original , policy : # dao_policy , oracle : # safety_wrapper) } } } } } } } fn is_syscall_function (& self , path : & syn :: Path) -> Option < & SyscallWrapper > { let path_str = path . segments . last () ? . ident . to_string () ; for (pattern , wrapper) in & self . interceptor . syscall_mappings { if path_str . contains (pattern) { return Some (wrapper) ; } } None } }
}